    /// Available since API-level: 18
    #[cfg(feature = "api-18")]
    #[cfg_attr(docsrs, doc(cfg(feature = "api-18")))]
    pub fn OH_HiAppEvent_DestroyProcessor(processor: *mut HiAppEvent_Processor);
    /// Removes a processor. Once a processor is removed, it stops reporting events. Note: This API only stops the
    /// processor reporting events but does not destroy the processor. You can call [`OH_HiAppEvent_DestroyProcessor`](crate::hiappevent::OH_HiAppEvent_DestroyProcessor) to
    /// destroy the processor and release the memory.
    ///
    /// # Arguments
