    /// - [`HIAPPEVENT_PROCESSOR_NOT_FOUND`](crate::hiappevent::HiAppEvent_ErrorCode::HIAPPEVENT_PROCESSOR_NOT_FOUND): Failed to find the processor.
    /// - [`HIAPPEVENT_OPERATE_FAILED`](crate::hiappevent::HiAppEvent_ErrorCode::HIAPPEVENT_OPERATE_FAILED): Operation failed.
    /// - [`HIAPPEVENT_INVALID_UID`](crate::hiappevent::HiAppEvent_ErrorCode::HIAPPEVENT_INVALID_UID): Invalid user ID.
    ///
    /// For details, see [`HiAppEvent_ErrorCode`](crate::hiappevent::HiAppEvent_ErrorCode).
    ///
    /// Available since API-level: 18
    #[cfg(feature = "api-18")]
    #[cfg_attr(docsrs, doc(cfg(feature = "api-18")))]
    pub fn OH_HiAppEvent_RemoveProcessor(processorId: i64) -> ::core::ffi::c_int;
    /// Creates a pointer to the configuration object that sets the conditions for triggering system events. Note: If
